'use strict';

// MODULES //

var tape = require( 'tape' );
var isAlmostSameValue = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var expf = require( '@stdlib/math/base/special/expf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var randu = require( '@stdlib/random/base/randu' );
var EPS = require( '@stdlib/constants/float32/eps' );
var log1pexpf = require( './../lib' );


// FIXTURES //

var small = require( './fixtures/python/small.json' );
var medium = require( './fixtures/python/medium.json' );
var large = require( './fixtures/python/large.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof log1pexpf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN`, the function returns `NaN`', function test( t ) {
	var v = log1pexpf( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes the natural logarithm of `1+exp(x)` (`x <= -17.0`)', function test( t ) {
	var x;
	var y;
	var v;
	var i;

	for ( i = 0; i < 1e3; i++ ) {
		v = f32( -17.0 - ( randu() * 100.0 ) );
		x = log1pexpf( v );
		y = expf( v );
		t.strictEqual( x, y, 'returns ' + y + ' when provided ' + v );
	}
	t.end();
});

tape( 'the function computes the natural logarithm of `1+exp(x)` (`x > 16.0`)', function test( t ) {
	var x;
	var v;
	var i;

	for ( i = 0; i < 1e3; i++ ) {
		v = f32( 16.0 + EPS + ( randu() * 100.0 ) );
		x = log1pexpf( v );
		t.strictEqual( x, v, 'returns ' + v + ' when provided ' + v );
	}
	t.end();
});

tape( 'the function accurately computes the natural logarithm of `1+exp(x)` (small values)', function test( t ) {
	var expected;
	var actual;
	var x;
	var i;

	x = small.x;
	expected = small.expected;
	for ( i = 0; i < x.length; i++ ) {
		actual = log1pexpf( x[ i ] );
		if ( actual === expected[ i ] ) {
			t.strictEqual( actual, expected[ i ], 'returns '+actual+' when provided ' + x[ i ] );
		} else {
			t.strictEqual( isAlmostSameValue( actual, expected[ i ], 2 ), true, 'returns expected value' );
		}
	}
	t.end();
});

tape( 'the function accurately computes the natural logarithm of `1+exp(x)` (medium values)', function test( t ) {
	var expected;
	var actual;
	var x;
	var i;

	x = medium.x;
	expected = medium.expected;
	for ( i = 0; i < x.length; i++ ) {
		actual = log1pexpf( x[ i ] );
		if ( actual === expected[ i ] ) {
			t.strictEqual( actual, expected[ i ], 'returns '+actual+' when provided ' + x[ i ] );
		} else {
			t.strictEqual( isAlmostSameValue( actual, expected[ i ], 2 ), true, 'returns expected value' );
		}
	}
	t.end();
});

tape( 'the function accurately computes the natural logarithm of `1+exp(x)` (large values)', function test( t ) {
	var expected;
	var actual;
	var x;
	var i;

	x = large.x;
	expected = large.expected;
	for ( i = 0; i < x.length; i++ ) {
		actual = log1pexpf( x[ i ] );
		if ( actual === expected[ i ] ) {
			t.strictEqual( actual, expected[ i ], 'returns '+actual+' when provided ' + x[ i ] );
		} else {
			t.strictEqual( isAlmostSameValue( actual, expected[ i ], 2 ), true, 'returns expected value' );
		}
	}
	t.end();
});
